+}
+
+impl Widget for SelectionOverlay {
+    fn render(self, area: Rect, buffer: &mut Buffer) {
+        let inner_width = area.width.saturating_sub(2);
+        let inner_height = area.height.saturating_sub(2);
+        if inner_width == 0 || inner_height == 0 {
+            return;
+        }
+
+        let inner_x = area.x.saturating_add(1);
+        let inner_y = area.y.saturating_add(1);
+        let style = Style::default().add_modifier(Modifier::REVERSED);
+        for range in self.ranges {
+            let Ok(row) = u16::try_from(range.row) else {
+                continue;
+            };
+            if row >= inner_height {
+                continue;
+            }
+
+            let start_column = range.start_column.min(usize::from(inner_width));
+            let end_column = range.end_column.min(usize::from(inner_width));
+            if start_column >= end_column {
+                continue;
+            }
+
+            for column in start_column..end_column {
+                let Ok(column) = u16::try_from(column) else {
+                    continue;
+                };
+                buffer
+                    .get_mut(inner_x.saturating_add(column), inner_y.saturating_add(row))
+                    .set_style(style);
+            }
+        }
+    }
+}
