+    fn visual_start_position(&self) -> VisualPosition {
+        match self.focus {
+            PaneFocus::Left => VisualPosition {
+                row: self.control_selected,
+                column: 0,
+            },
+            PaneFocus::Right => VisualPosition { row: 0, column: 0 },
+        }
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize) {
+        let Some(selection) = self.visual_selection.as_mut() else {
+            return;
+        };
+
+        selection.cursor.row = if row_delta.is_negative() {
+            selection.cursor.row.saturating_sub(row_delta.unsigned_abs())
+        } else {
+            selection.cursor.row.saturating_add(row_delta as usize)
+        };
+        selection.cursor.column = if column_delta.is_negative() {
+            selection
+                .cursor
+                .column
+                .saturating_sub(column_delta.unsigned_abs())
+        } else {
+            selection.cursor.column.saturating_add(column_delta as usize)
+        };
+    }
+
