+fn display_lines(content: &str, width: u16) -> Vec<String> {
+    let width = usize::from(width.max(1));
+    let mut lines = Vec::new();
+    for line in content.split('\n') {
+        if line.is_empty() {
+            lines.push(String::new());
+            continue;
+        }
+
+        let chars = line.chars().collect::<Vec<_>>();
+        for chunk in chars.chunks(width) {
+            lines.push(chunk.iter().collect());
+        }
+    }
+    lines
+}
+
+fn selection_ranges(
+    lines: &[String],
+    mode: VisualMode,
+    anchor: VisualPosition,
+    cursor: VisualPosition,
+) -> Vec<LineSelectionRange> {
+    if lines.is_empty() {
+        return Vec::new();
+    }
+
+    match mode {
+        VisualMode::Line => line_selection_ranges(lines, anchor, cursor),
+        VisualMode::Character => character_selection_ranges(lines, anchor, cursor),
+        VisualMode::Block => block_selection_ranges(lines, anchor, cursor),
+    }
+}
+
+fn line_selection_ranges(
+    lines: &[String],
+    anchor: VisualPosition,
+    cursor: VisualPosition,
+) -> Vec<LineSelectionRange> {
+    let (start_row, end_row) = selected_row_range(lines, anchor, cursor);
+    (start_row..=end_row)
+        .map(|row| {
+            let width = lines[row].chars().count().max(1);
+            LineSelectionRange {
+                row,
+                start_column: 0,
+                end_column: width,
+            }
+        })
+        .collect()
+}
+
+fn character_selection_ranges(
+    lines: &[String],
+    anchor: VisualPosition,
+    cursor: VisualPosition,
+) -> Vec<LineSelectionRange> {
+    let (start, end) = ordered_positions(clamped_position(lines, anchor), clamped_position(lines, cursor));
+    (start.row..=end.row)
+        .filter_map(|row| {
+            let line_width = lines[row].chars().count();
+            let start_column = if row == start.row { start.column } else { 0 }.min(line_width);
+            let end_column = if row == end.row {
+                end.column.saturating_add(1)
+            } else {
+                line_width
+            }
+            .min(line_width);
+            (start_column < end_column).then_some(LineSelectionRange {
+                row,
+                start_column,
+                end_column,
+            })
+        })
+        .collect()
+}
+
+fn block_selection_ranges(
+    lines: &[String],
+    anchor: VisualPosition,
+    cursor: VisualPosition,
+) -> Vec<LineSelectionRange> {
+    let (start_row, end_row) = selected_row_range(lines, anchor, cursor);
+    let start_column = anchor.column.min(cursor.column);
+    let end_column = anchor.column.max(cursor.column).saturating_add(1);
+    (start_row..=end_row)
+        .filter_map(|row| {
+            let line_width = lines[row].chars().count();
+            let start_column = start_column.min(line_width);
+            let end_column = end_column.min(line_width);
+            (start_column < end_column).then_some(LineSelectionRange {
+                row,
+                start_column,
+                end_column,
+            })
+        })
+        .collect()
+}
+
+fn selected_text(lines: &[String], request: YankRequest) -> Option<String> {
+    if lines.is_empty() {
+        return None;
+    }
+
+    let text = match request.mode {
+        VisualMode::Line => selected_line_text(lines, request.anchor, request.cursor),
+        VisualMode::Character => selected_character_text(lines, request.anchor, request.cursor),
+        VisualMode::Block => selected_block_text(lines, request.anchor, request.cursor),
+    };
+    Some(text)
+}
+
+fn selected_line_text(
+    lines: &[String],
+    anchor: VisualPosition,
+    cursor: VisualPosition,
+) -> String {
+    let (start_row, end_row) = selected_row_range(lines, anchor, cursor);
+    let mut text = lines[start_row..=end_row].join("\n");
+    text.push('\n');
+    text
+}
+
+fn selected_character_text(
+    lines: &[String],
+    anchor: VisualPosition,
+    cursor: VisualPosition,
+) -> String {
+    let (start, end) = ordered_positions(clamped_position(lines, anchor), clamped_position(lines, cursor));
+    let mut selected = Vec::new();
+    for row in start.row..=end.row {
+        let line_width = lines[row].chars().count();
+        let start_column = if row == start.row { start.column } else { 0 }.min(line_width);
+        let end_column = if row == end.row {
+            end.column.saturating_add(1)
+        } else {
+            line_width
+        }
+        .min(line_width);
+        selected.push(char_slice(&lines[row], start_column, end_column));
+    }
+    selected.join("\n")
+}
+
+fn selected_block_text(
+    lines: &[String],
+    anchor: VisualPosition,
+    cursor: VisualPosition,
+) -> String {
+    let (start_row, end_row) = selected_row_range(lines, anchor, cursor);
+    let start_column = anchor.column.min(cursor.column);
+    let end_column = anchor.column.max(cursor.column).saturating_add(1);
+    (start_row..=end_row)
+        .map(|row| char_slice(&lines[row], start_column, end_column))
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn selected_row_range(
+    lines: &[String],
+    anchor: VisualPosition,
+    cursor: VisualPosition,
+) -> (usize, usize) {
+    let last_row = lines.len().saturating_sub(1);
+    (
+        anchor.row.min(cursor.row).min(last_row),
+        anchor.row.max(cursor.row).min(last_row),
+    )
+}
+
+fn clamped_position(lines: &[String], position: VisualPosition) -> VisualPosition {
+    let row = position.row.min(lines.len().saturating_sub(1));
+    let line_width = lines
+        .get(row)
+        .map(|line| line.chars().count())
+        .unwrap_or_default();
+    VisualPosition {
+        row,
+        column: position.column.min(line_width.saturating_sub(1)),
+    }
+}
+
+fn ordered_positions(
